+            )
+            .setMapping("data", "type=keyword", "l", "type=long")
+            .get();
+        client().admin().cluster().prepareHealth(TEST_REQUEST_TIMEOUT).setWaitForGreenStatus().get();
+
+        String[] data = new String[] { "aa", "bb", "cc", "dd" };
