+        return getMatchingFieldNames(fieldNamePattern).stream()
+            .map(fieldName -> tuple(fieldName, getFieldType(fieldName)))
+            .filter(searchableFieldFilter.and(Predicate.not(ignoredFieldFilter)))
+            .collect(Collectors.toList());
+    }
