+                );
+                assertThat(parsedQuery, equalTo(parseKqlQuery(Strings.format("(NOT %s) AND %s", queryA, queryB))));
+            }
+
+            // <QueryA> OR <QueryB> is equivalent to (NOT <QueryA>) OR <QueryB>
+            {
